window.Views = (()=>{
 const {esc,icon,mark,button:B,link:L,top,tabs,row,bottle,bottleGrid,portraitMap,composer,empty}=UI;
 const section=(title,action='')=>`<div class="section-head"><h2>${title}</h2>${action}</div>`;
 const end=(txt='不急着定义自己。')=>`<p class="endnote">${txt}</p>`;
 const demo=()=>`<span class="pill outline"></span>`;
 const page=(content)=>content;
 function home(s){
  const active=s.sessions.find(x=>x.id===s.activeSession);const unfinished=active&&active.status==='in-progress';const done=active&&active.status==='completed';
  const entry=unfinished?`<div class="row between"><div><span class="overline">接着上次，不用重新开始</span><h2 class="entry-title space-8">继续答题体验</h2></div><span class="entry-symbol">${icon('bottle')}</span></div><p class="small muted space-12">已保存 ${Object.keys(active.answers).length} / 3 题 · ${active.mode==='ai'?'AI 重置方向':'原版方向'}演示</p><div class="resume-progress"><span style="width:${Object.keys(active.answers).length/3*100}%"></span></div>${B('继续第 '+(active.index+1)+' 题','resume',{cls:'btn full',after:'arrow'})}<div class="foot"><span>保持同一份答卷与版本</span>${L('查看已答','review',{cls:'textbtn','data-id':active.id})}</div>`:done?`<div class="row between"><div><span class="overline">这一次，你已经走完了</span><h2 class="entry-title space-8">先看看，再理解</h2></div><span class="entry-symbol">${icon('check')}</span></div><p class="small muted space-12">3 道体验题已完成。这不是正式测评，不生成你的性格结论。</p>${L('查看我的报告','report',{cls:'btn full space-16',after:'arrow','data-id':D.report.id})}<div class="foot">${L('回看这次作答','review',{cls:'textbtn','data-id':active.id})}${B('再体验一次','start-new',{cls:'textbtn'})}</div>`:`<div class="row between"><div><span class="overline">从一个完整的角度开始</span><h2 class="entry-title space-8">16PF 性格探索</h2></div><span class="entry-symbol">${icon('bottle')}</span></div><div class="segmented" aria-label="测评版本选择">${[['original','原版 16PF'],['ai','AI 重置版']].map(([id,label])=>`<button data-action="mode" data-id="${id}" class="${s.mode===id?'selected':''}" aria-pressed="${s.mode===id}">${label}</button>`).join('')}</div><p class="statusline">${s.mode==='original'?'正式题源与使用依据待落实；先试 3 道交互示例。':'AI 改编方向，尚未验证；不等同原版 16PF。'}</p>${B('体验 3 道示例题','start',{cls:'btn full',after:'arrow'})}<div class="foot"><span>约 1 分钟 · 不产生测评分数</span>${L('先看报告样例','report',{cls:'textbtn','data-id':D.report.id})}</div>`;
  return page(`<section class="home-hero"><div class="hero-copy"><span class="overline">${unfinished?'欢迎回来':'从好奇开始'}</span><h1 class="space-12">${unfinished?'慢慢来，<br>我们接着看。':done?'认识自己，<br>也认识变化。':'你的样子，<br>不止一种。'}</h1><p>${unfinished?'上次停下的地方，<br>这次可以接着走。':'看见自己的倾向，<br>也给不同的情境留点空间。'}</p></div><div class="person-scene"><span class="scene-line"></span><span class="scene-spark">${icon('sparkle')}</span><img src="assets/person-${s.avatar}.svg" alt="手拿笔记本的原创人物插画"></div></section><section class="entry">${entry}</section>${section('今天，也可以轻一点')}<button class="daily-row" data-action="daily"><span class="symbol">${icon('sun','lg')}</span><span class="grow"><strong>每日轻探索</strong><p>轻量题组未就绪，也可以先记一句。</p></span>${icon('chevron','sm')}</button><div class="mini-grid"><button class="mini-tile" data-action="all-factors">${icon('bottle')}<strong>先了解一个因子</strong><p>从你感兴趣的角度开始 ${icon('chevron','sm')}</p></button><button class="mini-tile" data-action="nav" data-route="simulation">${icon('explore')}<strong>做个假设</strong><p>看看不同倾向的组合 ${icon('chevron','sm')}</p></button></div>${section('多一点理解，少一点标签')}<button class="reading-row" data-action="nav" data-route="article" data-id="read-traits"><span class="reading-number">01</span><span class="grow"><h3>高一点、低一点，都不代表更好</h3><p>读懂因子瓶，先从一个误解说起。</p></span>${icon('chevron','sm')}</button><button class="reading-row" data-action="nav" data-route="records"><span class="reading-number">02</span><span class="grow"><h3>看看之前，自己怎么说</h3><p>找回测评、观察和当时的情境。</p></span>${icon('chevron','sm')}</button>${end()}`);
 }
 function topicCard(t,feature=false){if(feature)return `<button class="feature-topic" data-action="nav" data-route="topic" data-id="${t.id}"><span class="pill outline">${t.short} · 内容策划</span><h2>留在熟悉的地方，<br>还是试一条新路？</h2><p class="small muted space-12" style="max-width:67%">先分清，你想离开的是什么，<br>又想靠近什么。</p><span class="topic-cta">看看这组问题 ${icon('arrow','sm')}</span><img src="assets/paths.svg" alt="两条分开的探索路径"></button>`;return `<button class="topic-card ${t.color}" data-action="nav" data-route="topic" data-id="${t.id}"><span class="pill">${t.category} · 内容策划</span><h3>${t.title}</h3><p class="small muted">${t.desc}</p><img src="assets/${t.art}.svg" alt=""><span class="card-foot">查看这组问题 ${icon('arrow','sm')}</span></button>`;}
 function explore(s){const cats=['全部','工作','相处','学习','生活'];let rows=D.topics.filter(t=>(s.exploreCategory==='全部'||t.category===s.exploreCategory)&&(!s.exploreSearch||[t.title,t.desc,t.category].join(' ').includes(s.exploreSearch)));const feature=rows.find(t=>t.id==='work-choice');return `<div class="topline"><span class="overline">从生活里的问题出发</span>${B('已收藏','favorites',{cls:'textbtn',icon:'bookmark'})}</div><header class="explore-head"><h1>最近，<br>你在想什么？</h1><p class="small muted space-12">从一个具体的问题，找到理解自己的线索。</p></header><div class="search space-24">${icon('search')}<label class="sr-only" for="explore-search">搜索生活主题</label><input id="explore-search" value="${esc(s.exploreSearch)}" data-input="explore-search" placeholder="搜索工作、相处、城市…" maxlength="100">${B('','clear-search',{cls:'',icon:s.exploreSearch?'close':'filter','aria-label':s.exploreSearch?'清空搜索':'查看筛选方式'})}</div><div class="chips" aria-label="生活主题">${cats.map(c=>`<button data-action="category" data-id="${c}" class="${s.exploreCategory===c?'active':''}" aria-pressed="${s.exploreCategory===c}">${c}</button>`).join('')}</div><div id="topic-results">${feature?topicCard(feature,true):''}${rows.length?`${section(feature?'也许，你还关心这些':'与你的问题有关',`<span class="small muted">${rows.length} 个方向</span>`)}<div class="topic-grid">${rows.filter(t=>t!==feature).map(t=>topicCard(t)).join('')}</div>`:empty('暂时没有找到','换一个关键词，或回到全部主题。',B('查看全部','clear-filters',{cls:'btn tonal compact'}))}</div><div class="hint space-24">这里展示的是专题设计方向，正式题组和适用依据尚未上线。先梳理条件，不让测评替你做决定。</div>${end('答案不必相同，重要的是更清楚自己的在意。')}`;}
 function assistant(s){return `<div class="topline"><span class="overline">你的个人助理</span>${B(s.logged?`演示剩余 ${Math.max(0,10-s.used)} / 10`:'登录后，每日共用 10 次','quota',{cls:'quota-pill',icon:'info'})}</div><header class="assistant-head"><div class="assistant-motif">${icon('chat')}</div><h1>把说不清的，<br>一起理一理。</h1><p>不急着给你答案。<br>先从最近的一件事，或一份报告说起。</p></header><div class="prompt-chips"><button data-action="prompt" data-id="report">${icon('book')}关于一份报告 ${icon('arrow','sm')}</button><button data-action="prompt" data-id="recent">${icon('leaf')}关于最近的事 ${icon('arrow','sm')}</button></div>${composer(s.assistantDraft,s.assistantSources,s.logged)}<p class="privacy-caption">${icon('shield','sm')}<span>本次引用由你选择，不会自动成为长期记忆。当前回复为预写演示，不联网。</span></p>${section('接着上次聊',L('全部对话','conversations',{cls:'textbtn'}))}${s.conversations.length?s.conversations.slice(-2).reverse().map(c=>`<button class="history-row" data-action="nav" data-route="conversation" data-id="${c.id}">${icon('chat')}<span class="grow"><h3>${esc(c.title)}</h3><small>${esc(c.updatedLabel||'本机演示对话')} · ${c.messages.length} 条消息</small></span>${icon('chevron','sm')}</button>`).join(''):`<p class="small muted">还没有对话。写下的草稿会留在这里，登录后由你决定是否发送。</p>`}<div class="plain-list space-24">${row('助理记住了什么','确认、纠正，或停止使用一条记忆','memories','memory')}</div>${end('你说了什么，和助理记住什么，是两件事。')}`;}
 function me(s){return `<div class="topline"><span class="overline">我的</span>${L('','settings',{cls:'iconbtn',icon:'settings','aria-label':'打开设置'})}</div><div class="profile-header"><div class="profile-avatar"><img src="assets/person-${s.avatar}.svg" alt="我的插画形象"></div><div class="grow"><h1>${esc(s.name)}</h1><span class="pill outline space-8">${icon('folder','sm')} 本机空间</span></div>${B('','edit-name',{cls:'iconbtn',icon:'edit','aria-label':'修改称呼'})}</div><section class="portrait-card"><div class="row between"><h2>正在认识的自己</h2>${L('展开','portrait',{cls:'textbtn',after:'chevron'})}</div>${portraitMap(s.observations.length+s.reportNotes.length)}<p class="small muted">${s.observations.length+s.reportNotes.length?'你的经历已经留下了线索。它们是本人记录，不会自动变成测评结论。':'还没有依据的地方，先留白。你不需要马上成为某一种人。'}</p>${L('记下一个自己的时刻','journal',{cls:'btn secondary full space-16',icon:'plus'})}</section><div class="profile-pair"><button data-action="nav" data-route="records">${icon('book')}<strong>${s.sessions.length+s.observations.length+s.reportNotes.length}</strong><span>测评与记录</span><small>属于这台设备的积累</small></button><button data-action="nav" data-route="actions">${icon('flag')}<strong>${s.actions.length}</strong><span>我的小尝试</span><small>不用打卡，也可以回看</small></button></div>${section('我的理解，由我掌握')}<div class="plain-list">${row('助理记忆','看见来源，也能随时纠正','memories','memory')}${row('我的数据','查看本机保存范围与导出','data','folder')}${row('隐私与引用','聊天留存和长期记忆分别控制','privacy','shield')}</div>${section('按自己的方式使用')}<div class="plain-list">${row(s.logged?'演示账号':'登录 / 创建账号',s.logged?'当前仅为本地模拟身份':'不登录，也能保留本机记录',s.logged?'account':'auth','user')}${row('设置','主题、形象与阅读习惯','settings','settings')}${row('会员与使用次数','规则先看清，个人资料不作续费筹码','membership','crown')}${row('帮助与说明','', 'support','help')}</div>${end('知遇测评 · 给认识自己留一点空间。')}`;}
 function question(s,p){const sess=App.getSession(p.id);if(!sess)return missing('这份答卷暂时找不到','records');const q=D.questions[sess.index];if(!q)return missing('题目版本无法恢复','records');const selected=App.pendingAnswer?.sessionId===sess.id&&App.pendingAnswer?.qid===q.id?App.pendingAnswer.choice:sess.answers[q.id];const fail=!!App.pendingAnswer;const saved=!!sess.answers[q.id]&&!fail;return `<div class="question-top">${B('暂停','pause',{cls:'back',icon:'pause'})}<span class="question-count"><strong>${String(sess.index+1).padStart(2,'0')}</strong> / 03</span></div><div class="progress" role="progressbar" aria-label="答题进度" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${Object.keys(sess.answers).length}"><span style="width:${Object.keys(sess.answers).length/3*100}%"></span></div><section class="question-main">${demo()}${sess.factorId?`<span class="pill space-8">当前角度 ${esc(sess.factorId)}</span>`:''}<h1>${q.title}</h1><p>选更像平时的，不用选“更好”的。</p><div class="options" role="radiogroup" aria-label="选择一个答案">${q.options.map(([id,text])=>`<button class="option ${selected===id?'selected':''}" role="radio" aria-checked="${selected===id}" data-action="answer" data-id="${id}" tabindex="${selected?selected===id?'0':'-1':id==='a'?'0':'-1'}"><span class="letter">${selected===id?icon('check','sm'):id.toUpperCase()}</span><span>${text}${selected===id?'<span class="checklabel">已选择</span>':''}</span></button>`).join('')}</div>${fail?`<div class="hint error space-16" role="alert"><strong>这次选择还没有存好。</strong><p class="small">选项仍保留在当前页面。先重试，保存成功后再继续；不要关闭窗口。</p><div class="row wrap space-8">${B('重试保存','retry-save',{cls:'btn secondary compact',icon:'refresh'})}${B('导出临时答案','rescue',{cls:'textbtn',icon:'download'})}</div></div>`:`<p class="save-status" role="status">${icon(saved?'check':'info','sm')}${saved?'已保存到本机 · 可随时暂停':'请选择一个选项，选中后保存到本机。'}</p>`}<p class="small muted space-16"></p></section>`;}
 function review(s,p){const sess=App.getSession(p.id);if(!sess)return missing('这份答卷暂时找不到','records');const done=sess.status==='completed';return `${top('返回')}<span class="overline">${done?'已保存的作答':'最后，再看一眼'}</span><h1 class="info-title">${done?'这是你当时的选择':'看看这次的选择'}</h1><p class="small muted">${done?'只读保留，不覆盖原记录。重新体验会建立另一份答卷。':'可以返回修改。确认完成后，保留这次作答。'}</p>${D.questions.map((q,i)=>`<div class="review-item"><div class="row"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="grow"><p>${q.title}</p><div class="answer">${q.options.find(o=>o[0]===sess.answers[q.id])?.[1]||'尚未作答'}</div></div>${done?'':B('修改','edit-answer',{cls:'textbtn','data-index':i,'data-id':sess.id})}</div></div>`).join('')}<div class="hint space-24">这里保留的是你当时选择的回答。</div>${done?L('查看我的报告','report',{cls:'btn full space-24','data-id':D.report.id}):B('保存这次作答','finish',{cls:'btn full space-24','data-id':sess.id,disabled:Object.keys(sess.answers).length!==3})}`;}
 function complete(s,p){const sess=App.getSession(p.id);if(!sess||sess.status!=='completed')return missing('还没有完成这份体验答卷','records');return `${top('回到认识')}<div class="completion-graphic"><img src="assets/sprout.svg" alt="一株正在生长的小芽"><span class="check-circle">${icon('check')}</span></div><div class="center"><span class="overline">这一次，已经留了下来</span><h1 class="space-16">不用一下子，<br>就把自己看明白。</h1><p class="muted space-16">3 道示例题已保存在本机。<br>你随时可以回来看看。</p></div><div class="hint space-32">这次没有生成个人测评结论。下一页是虚构人物的报告样例，可以看看解读如何结合具体情境。</div>${L('查看独立报告样例','report',{cls:'btn full space-24','data-id':D.report.id,after:'arrow'})}${L('回到认识','home',{cls:'btn secondary full space-12'})}${end()}`;}
 function report(s,p){if(p.id&&p.id!==D.report.id)return missing('这份报告不在当前空间','records');const work=s.reportContext!=='relationship';const source=D.reportSource(work?'work':'relationship');const note=App.formDrafts.reportNote??'';return `${top('返回',B('','nav',{cls:'iconbtn',icon:'share','data-route':'share','aria-label':'选择分享范围','data-id':D.report.id}))}<section class="report-hero"><div class="report-meta"><span class="pill outline">独立报告样例</span><span>虚构案例 · 不来自演示作答</span></div><h1>${work?'先想清楚，<br>再慢慢说出来。':'熟悉之后，<br>你有自己的热络。'}</h1><p class="lead">${work?'一段准备时间，可能让表达更从容。<br>这可以先保留为一个值得观察的条件，无需急着贴上“不擅长”的标签。':'安静和愿意靠近别人，可以同时存在。<br>情境不同，表达自己的方式也会不同。'}</p><div class="rule"></div></section><div class="report-body"><div class="context-switch" aria-label="报告情境"><button class="${work?'active':''}" data-action="report-context" data-id="work" aria-pressed="${work}">在工作里</button><button class="${!work?'active':''}" data-action="report-context" data-id="relationship" aria-pressed="${!work}">在相处中</button></div><h2>从一件小事，看见一种可能</h2><blockquote class="quote"><div class="caption">虚构生活片段 · 小林</div>${source.excerpt}</blockquote><p>${work?'不妨把注意力从“我是不是不善表达”，转向“什么条件让我表达得更清楚”。准备时间、话题熟悉度和参与人数，都可以分别观察。':'先听一会儿，和主动参与，并不是相互排斥的特点。与谁在一起、话题是否熟悉、自己当天的状态，都值得一起看。'}</p><div class="two-notes"><section><h3>${icon('leaf','sm')} 可能有帮助的地方</h3><p>${work?'有机会整理时，更容易说明理由，顾及细节。':'在熟悉的关系里，可能更愿意认真回应、慢慢展开。'}</p></section><section><h3>${icon('info','sm')} 也值得留意</h3><p>${work?'等待完全想好，可能让一些发言机会悄悄过去。':'在新场合沉默太久，别人可能还不知道你也想加入。'}</p></section></div>${B('看看这段依据','source-report',{cls:'source-row',icon:'link',after:'chevron'})}<section class="report-section"><h2>16 个角度，放在一起看</h2><p>每只瓶子是一个因子。点开看解释，不把“更满”理解成“更好”。</p>${bottleGrid()}<div class="bottle-legend"><span><i class="swatch"></i>样例位置，非个人得分</span><span><i class="swatch gray"></i>暂无依据，不是零分</span></div></section><section class="report-section"><span class="pill outline">本人补充</span><h2 class="space-12">你的经历，比标签更具体</h2><p>哪些像你，哪些不太像？写下情境，不会改写任何测评分数。</p><div class="editor"><label class="field-label" for="report-note">留一句自己的补充</label><textarea class="textarea" id="report-note" data-input="report-note" placeholder="比如：熟悉的人面前，我其实更愿意主动表达。" maxlength="1500">${esc(note)}</textarea>${B('保存我的补充','save-report-note',{cls:'btn secondary',icon:'edit'})}</div>${s.reportNotes.length?`<p class="small muted space-12">已保留 ${s.reportNotes.length} 条本人补充。${L('在记录中查看','records',{cls:'textbtn'})}</p>`:''}</section><section class="action-note"><div class="head">${icon('flag')}<h3>下次，试一个小变化</h3></div><p>${work?'下次临时被问到时，可以先说：“给我一点整理时间，我从两点说起。”':'下次想加入一段对话时，可以先接住一个具体细节：“刚才你说的那件事，我也有一点类似的感受。”'}</p>${B('把这个小尝试留下','add-action',{cls:'textbtn',after:'arrow','data-context':work?'work':'relationship'})}</section><div class="report-bottom">${B('拿这段情境，和助理聊聊','quote-report',{cls:'btn full',icon:'chat'})}${L('回到认识','home',{cls:'btn secondary full'})}</div><details><summary>这份样例的边界与来源</summary><p>生活片段和瓶中位置均为本轮设计创作的虚构材料，没有使用真实答卷、正式计分或常模。因子名称为界面工作译名，正式中文版本及解释依据仍须核对。主题颜色不代表评价，未知值不显示为零。</p></details></div>${end('一份报告，是理解的起点，不是对你的定论。')}`;}
 function records(s){let items=[];s.sessions.forEach(x=>items.push({id:x.id,type:x.status==='completed'?'体验答卷':'未完成',title:'3 题交互体验',desc:x.status==='completed'?'只读体验答卷 · 不产生性格结论':`已保存 ${Object.keys(x.answers).length} / 3 题 · 原版本继续`,route:x.status==='completed'?'review':'question'}));s.observations.forEach(x=>items.push({id:x.id,type:'本人观察',title:x.title||'一个自己的时刻',desc:x.text,route:'journal'}));s.reportNotes.forEach(x=>items.push({id:x.id,type:'报告补充',title:'我对报告样例的补充',desc:x.text,route:'journal'}));if(s.recordFilter!=='全部')items=items.filter(x=>x.type===s.recordFilter);return `${top('我的',B('写观察','nav',{cls:'btn tonal compact','data-route':'journal',icon:'plus'}))}<h1 class="info-title">留在这里的自己</h1><p class="small muted">按当时的情境回看，不合成一个“成长分”。</p><div class="chips">${['全部','未完成','体验答卷','本人观察','报告补充'].map(x=>`<button data-action="record-filter" data-id="${x}" class="${s.recordFilter===x?'active':''}">${x}</button>`).join('')}</div>${items.length?items.reverse().map(x=>`<button class="record-item" data-action="nav" data-route="${x.route}" data-id="${x.id}"><span class="pill outline">${x.type}</span><h3>${esc(x.title)}</h3><p class="summary">${esc(x.desc)}</p><div class="foot"><span>本机保存</span>${icon('arrow','sm')}</div></button>`).join(''):empty('还没有这类记录','先留下一段经历。以后回来，你会知道当时的自己怎么想。',L('写一个观察','journal',{cls:'btn tonal compact'}))}<div class="plain-list space-24">${row('两份记录怎样比较','先核对版本和量纲，不默认计算变化','compare','book')}</div>${end('当前没有真实 16PF 报告；独立样例不混入你的记录。')}`;}
 function topic(s,p){const t=D.topics.find(x=>x.id===p.id);if(!t)return missing('这个主题暂时找不到','explore');return `${top('探索',B('','favorite',{cls:'iconbtn',icon:'bookmark','data-id':t.id,'aria-label':s.favorites.includes(t.id)?'取消收藏':'收藏这个主题','aria-pressed':s.favorites.includes(t.id)}))}<span class="pill">${t.category} · 内容策划</span><h1 class="info-title">${t.title}</h1><p class="muted">${t.desc}</p><img src="assets/${t.art}.svg" style="width:180px;margin:20px auto" alt="主题插画"><h2>这次，先整理三个问题</h2><ol class="step-list">${t.prompts.map(x=>`<li>${x}</li>`).join('')}</ol><div class="hint"><strong>你能留下什么</strong><p class="small space-8">${t.output}</p></div><details open><summary>题组准备情况</summary><p>这里是专题策划与本地记录示例。正式测评题目、题量、适用人群、评分和解释依据均未定。本轮不根据回答推荐职业、城市或关系决定。</p></details>${B('先写下我的想法','topic-journal',{cls:'btn full','data-id':t.id,after:'arrow'})}`;}
 function appearance(s,p){return `${top('返回')}<span class="overline">按自己喜欢的方式</span><h1 class="info-title">换一种，舒服的感觉</h1><p class="small muted">主题与形象只改变外观，不改变测评或你的资料。</p><div class="home-hero" style="margin:4px 0 10px;min-height:205px"><div class="hero-copy"><span class="overline">此刻的色彩</span><h1 class="space-12" style="font-size:1.75rem">轻一点，<br>也鲜活一点。</h1></div><div class="person-scene" style="height:215px"><img src="assets/person-${s.avatar}.svg" alt="当前人物形象"></div></div>${section('主题色彩')}<div class="theme-options">${D.themes.map(t=>`<button class="theme-option ${s.theme===t.id?'selected':''}" data-action="theme" data-id="${t.id}" aria-pressed="${s.theme===t.id}"><span class="theme-swatch" style="background:linear-gradient(125deg,${t.colors.join(',')})"></span><span class="grow"><strong>${t.name}</strong><small>${t.desc}</small></span>${s.theme===t.id?icon('check'):''}</button>`).join('')}</div><div class="switch-row"><span class="grow">减少动态<span class="small muted" style="display:block">系统减少动态优先；启用后保留静态色彩。</span></span><button class="switch ${s.reduced?'on':''}" role="switch" aria-checked="${s.reduced}" aria-label="减少动态" data-action="toggle-motion"><span></span></button></div>${section('我的形象')}<div class="avatar-options">${[1,2,3].map(i=>`<button class="${s.avatar===i?'selected':''}" data-action="avatar" data-id="${i}" aria-pressed="${s.avatar===i}"><img src="assets/person-${i}.svg" alt="人物预设 ${i}"><span>预设 ${String(i).padStart(2,'0')}</span></button>`).join('')}</div><p class="small muted space-16">本轮提供 3 个原创矢量预设。自由捏脸、部件编辑属于后续方案，没有假装已接入素材库。</p>${end('换一个外观，不必重新开始。')}`;}
 function conversations(s){return `${top('助理',L('新话题','assistant',{cls:'btn tonal compact',icon:'plus'}))}<h1 class="info-title">我们聊过的</h1><p class="small muted">回到同一段对话，不会重新生成或再扣次数。</p><div class="space-24">${s.conversations.length?s.conversations.slice().reverse().map(c=>`<button class="history-row" data-action="nav" data-route="conversation" data-id="${c.id}">${icon('chat')}<span class="grow"><h3>${esc(c.title)}</h3><small>${esc(c.updatedLabel||'本机演示')} · ${c.messages.length} 条消息</small></span>${icon('chevron','sm')}</button>`).join(''):empty('还没有对话','你可以先准备一个问题，登录后再决定是否发送。',L('准备一个问题','assistant',{cls:'btn tonal compact'}))}</div>`;}
 function conversation(s,p){const c=s.conversations.find(x=>x.id===p.id);if(!c)return missing('这段对话不在当前空间','conversations');return `${top('返回对话',B('','conversation-settings',{cls:'iconbtn',icon:'more','aria-label':'这段对话的设置'}))}<h1 class="info-title" style="font-size:1.3125rem">${esc(c.title)}</h1><div class="chat-label"><span class="pill gray">预写演示</span><span>不联网 · 不是实际 AI 回复</span></div>${c.messages.map(m=>m.role==='user'?`<div class="message user"><p>${esc(m.text).replace(/\n/g,'<br>')}</p>${m.sources?.length?`<div class="small muted space-8">${icon('link','sm')} 这次附带 ${m.sources.length} 份资料</div>`:''}</div>`:`<div class="message assistant"><div class="role">${icon('chat','sm')} 个人助理 <span class="pill outline">演示回复</span></div>${m.sources?.length?`<button class="sources-used" data-action="message-source" data-id="${m.id}">${icon('link','sm')} 参考：${m.sources.map(x=>esc(x.title)).join('、')} · 查看当时片段</button>`:''}<p>${esc(m.text).replace(/\n/g,'<br>')}</p>${m.status==='stopped'?'<p class="small muted">演示生成已停止，不自动重发。</p>':`<div class="message-tools">${B('留一个小尝试','add-action',{cls:'',icon:'flag'})}${B('提出一条记忆候选','candidate-memory',{cls:'',icon:'memory','data-id':m.id})}${B('不太符合','correct-response',{cls:'',icon:'edit','data-id':m.id})}</div>`}</div>`).join('')}${c.generating?`<div class="hint row between" role="status"><span>正在展示演示回复…</span>${B('停止','stop',{cls:'btn secondary compact'})}</div>`:''}${composer(c.draft||'',c.draftSources||[],s.logged,true)}<div class="privacy-caption">${icon('shield','sm')}<span>聊天是否保存，与是否长期记住，分开由你控制。</span></div>`;}
 function auth(s){return `${top('暂不登录')}<div class="assistant-motif">${icon('user')}</div><span class="overline">本机记录，不以登录为前提</span><h1 class="info-title">准备好，再继续聊</h1><p class="muted">登录是使用 AI 的前提。<br>刚才写下的内容和引用还在，不会自动发送。</p><div class="hint space-24"><strong>账号服务暂不可用</strong><p class="small space-8">无需填写手机号、验证码或密码。下方只进入一个本地演示身份，不创建账号，不上传或合并本机历史。</p></div><div class="plain-list space-24">${row('创建账号的正式流程','用途说明 → 本人同意 → 身份验证 → 回原草稿','','user','查看',{action:'auth-spec'})}</div>${B('用演示身份继续','demo-login',{cls:'btn full space-24',after:'arrow'})}${B('保留草稿，暂不登录','back',{cls:'btn secondary full space-12'})}<p class="small muted space-16">正式注册方式、适用年龄、协议和验证服务尚待确定。演示不验证身份，也不代表账号隔离已实现。</p>`;}
 function memories(s){return `${top('我的',B('引用设置','nav',{cls:'textbtn','data-route':'privacy'}))}<h1 class="info-title">值得记住的，<br>由你决定。</h1><p class="small muted">待确认的内容不会直接采用。你可以确认、修改或停用；当前仅在本机演示。</p>${s.memories.length?s.memories.map(m=>`<article class="record-item space-16"><div class="row between"><span class="pill ${m.status==='active'?'':'gray'}">${{candidate:'待你确认',active:'已确认',inactive:'已停用'}[m.status]||m.status}</span><span class="small muted">${esc(m.sourceType||'本人补充')}</span></div><h3>${esc(m.text)}</h3><p class="small muted space-8">${esc(m.sourceTitle||'本轮演示')} · ${m.status==='inactive'?'不再作为后续引用':'不会改变原始测评分数'}</p><div class="row wrap space-16">${m.status==='candidate'?B('确认采用','confirm-memory',{cls:'btn tonal compact','data-id':m.id}):m.status==='active'?B('停止使用','deactivate-memory',{cls:'btn secondary compact','data-id':m.id}):B('查看停用说明','inactive-info',{cls:'textbtn'})}${B('修改','edit-memory',{cls:'textbtn','data-id':m.id})}${B('删除','delete-memory',{cls:'textbtn','data-id':m.id})}</div></article>`).join(''):empty('还没有确认的记忆','聊过的内容不会自动成为记忆。你确认后，才会保存在这里。',L('回到助理','assistant',{cls:'btn tonal compact'}))}<div class="hint space-24">演示记忆只在当前浏览器保存，未接入真实 AI 或云端记忆服务。停用后，不再用于新的演示引用。</div>`;}
 function actions(s){return `${top('我的',B('新建','new-action',{cls:'btn tonal compact',icon:'plus'}))}<h1 class="info-title">试一点，<br>就已经有变化的可能。</h1><p class="small muted">不是待办清单，也没有连续打卡要求。挑一件值得试的小事。</p>${s.actions.length?s.actions.map(a=>`<article class="record-item space-20"><span class="pill ${a.status==='done'?'gray':''}">${a.status==='done'?'已回看':a.status==='cancelled'?'已放下':'准备试试'}</span><h3>${esc(a.text)}</h3>${a.observation?`<p class="summary">我的观察：${esc(a.observation)}</p>`:''}<div class="row wrap space-12">${a.status==='active'?B('记下尝试后的感受','review-action',{cls:'btn tonal compact','data-id':a.id}):B('查看 / 修改观察','review-action',{cls:'btn secondary compact','data-id':a.id})}${a.status==='active'?B('这次先不做','cancel-action',{cls:'textbtn','data-id':a.id}):''}</div></article>`).join(''):empty('还没有小尝试','从报告或一段对话里留下一件事，或者直接写一个自己的想法。',B('写一个小尝试','new-action',{cls:'btn tonal compact'}))}<div class="plain-list space-24">${row('只记观察，不安排事情','观察可以独立存在，不需要先建行动','journal','edit')}</div>`;}
 function journal(s,p){const found=s.observations.find(x=>x.id===p.id)||s.reportNotes.find(x=>x.id===p.id);const topic=D.topics.find(x=>x.id===p.topic);const title=topic?topic.title:p.kind==='daily'?'今天，什么时刻最像自己？':found?.title||'一个自己的时刻';const value=App.formDrafts.journal??found?.text??'';return `${top('返回')}<span class="pill outline">本人观察 · 可离线记录</span><h1 class="info-title">${title}</h1><p class="small muted">${topic?'把想法写下来。无需完整，也没有标准答案。':'记下发生了什么，以及你当时怎么想。不用替自己下结论。'}</p>${topic?`<div class="hint space-20">${topic.prompts.map((x,i)=>`<p class="small">${i+1}. ${x}</p>`).join('')}</div>`:''}<div class="space-24"><label class="field-label" for="journal-text">我的记录</label><textarea id="journal-text" class="textarea" data-input="journal" maxlength="4000" style="min-height:265px" placeholder="那一刻，我…">${esc(value)}</textarea></div><div class="privacy-caption">${icon('folder','sm')}<span>保存在本机；不自动交给 AI，也不自动成为长期记忆。</span></div>${B(found?'保存修改':'保存这个时刻','save-journal',{cls:'btn full space-24','data-id':p.id||'','data-title':title})}${found?B('删除这条记录','delete-journal',{cls:'textbtn full space-12','data-id':found.id}):''}`;}
 function portrait(s){const n=s.observations.length+s.reportNotes.length;return `${top('我的')}<span class="overline">留下线索，也留下未知</span><h1 class="info-title">不是一个标签，<br>是好多面的你。</h1><div class="portrait-card space-24">${portraitMap(n)}<p class="small muted">节点位置不表示能力高低；连线只说明来源关系。问号代表暂无依据，不是零分。</p></div>${section('目前能看到的来源')}<div class="plain-list">${row('本人观察',`${s.observations.length} 条 · 由你写下，不是测量结果`,'records','edit')}${row('报告补充',`${s.reportNotes.length} 条 · 本人陈述与原解释分开`,'records','book')}${row('确认的记忆',`${s.memories.filter(x=>x.status==='active').length} 条 · 仅显示仍有效的认识`,'memories','memory')}</div><div class="hint space-24">这里还没有正式测评结果。你写下的观察会单独保留，不会自动换算为人格分数。</div>${L('再留下一条观察','journal',{cls:'btn full space-24',icon:'plus'})}`;}
 function data(s){return `${top('我的')}<span class="overline">看得见，也拿得走</span><h1 class="info-title">我的数据</h1><div class="card space-24"><div class="row">${icon('folder')}<strong>当前浏览器 · 本机保存</strong></div><div class="data-figure">${s.sessions.length+s.observations.length+s.reportNotes.length+s.conversations.length+s.memories.length}<small> 份本机资料</small></div><p class="small muted">浏览器清理、隐私模式结束或换设备，可能让这些资料无法找回。保存到本机不等于已备份。</p></div><div class="plain-list space-20">${row('选择导出资料','先预览类别，再生成 JSON 备份','','download','',{action:'export-preview'})}${row('导入前了解范围','支持本机 JSON 备份；当前空间需为空','','upload','说明',{action:'import-spec'})}${row('备份和跨设备同步','未接入；不显示“已同步”','','refresh','未接入',{action:'sync-spec'})}${row('本地内容包','查看当前实际包含的演示内容','content','book')}${row('清理演示数据','仅清理当前体验空间；不会清除其他站点','','trash','',{action:'clear-confirm'})}</div><div class="hint space-24">当前演示没有私人资料云端、真实账号或模型服务。导出为未加密 JSON，请自行妥善保管，不要输入真实敏感信息。</div>`;}
 function membership(s){return `${top('返回',L('订单','orders',{cls:'textbtn'}))}<span class="overline">先看清规则，再作选择</span><h1 class="info-title">先了解使用规则</h1><p class="muted">会员尚未售卖。<br>先看已确认的规则和仍待明确的部分。</p><div class="card space-24"><div class="row between"><h2>免费使用</h2><span class="pill">已确认规则</span></div><dl class="order-facts" style="margin-bottom:0"><dt>未登录</dt><dd>不能使用 AI；本地内容仍可用</dd><dt>注册并登录</dt><dd>AI 分析与对话每日共用 10 次</dd><dt>已有记录</dt><dd>当前可本机查看、导出；正式服务规则待定</dd></dl></div>${section('会员方案 · 尚未售卖')}<p class="small muted">可以体验选择方案和查看演示订单。价格、额度、支付渠道与续费方式都未确定。</p>${[['monthly','月方案','按月了解服务'],['annual','年方案','更长期的服务方向']].map(([id,title,desc])=>`<button class="plan ${s.plan===id?'selected':''}" data-action="plan" data-id="${id}" aria-pressed="${s.plan===id}"><div class="row between"><strong>${title}</strong><span class="price">价格待定</span></div><p>${desc} · 具体权益待定</p></button>`).join('')}${B('查看购买确认演示','checkout-start',{cls:'btn full space-24',after:'arrow'})}<div class="plain-list space-20">${row('查看 AI 演示用量','分析与对话共用，不拆成两份','','clock','',{action:'quota'})}${row('已有购买恢复 / 续费管理','暂未接入，不能恢复真实购买','','refresh','方案',{action:'restore-spec'})}</div>${end('不会发起支付，不会创建真实订单。')}`;}
 function checkout(s){return `${top('返回方案')}<span class="pill outline">购买流程演示</span><h1 class="info-title">看看你选择的方案</h1><div class="order-heading space-24"><div class="row between"><h2>${s.plan==='annual'?'年方案':'月方案'}</h2><span class="pill outline">尚未定价</span></div><p class="small muted space-12">周期、权益和金额在正式售卖前必须明确。当前只能查看流程状态，不付款。</p></div><dl class="order-facts"><dt>购买身份</dt><dd>${s.logged?'本地演示账号':'未登录 · 演示订单不绑定真实身份'}</dd><dt>内容版本</dt><dd>proposal-v1 · 非有效报价</dd><dt>生效规则</dt><dd>尚未确定，当前不生效</dd><dt>付款渠道</dt><dd>未接入</dd><dt>金额</dt><dd>未定价，不扣款</dd></dl><div class="hint">只在当前浏览器生成一份演示订单，保留你选的方案。不会付款，也不会向支付平台提交。</div>${B('创建演示订单','create-order',{cls:'btn full space-24',after:'arrow'})}${B('取消，保留原草稿','cancel-checkout',{cls:'btn secondary full space-12'})}`;}
 function orders(s){return `${top('我的')}<h1 class="info-title">订单记录</h1><p class="small muted">这里保留创建演示订单时的方案和状态，没有真实交易。</p><div class="space-24">${s.orders.length?s.orders.slice().reverse().map(o=>`<button class="record-item" data-action="nav" data-route="order" data-id="${o.id}"><span class="pill outline">演示订单</span><h3>${o.plan==='annual'?'年方案':'月方案'}</h3><div class="foot"><span>${esc(o.id)}</span><span>${App.orderLabel(o)}</span></div></button>`).join(''):empty('还没有订单','当前未售卖真实会员，也没有真实扣款。',L('了解使用规则','membership',{cls:'btn tonal compact'}))}</div>`;}
 function order(s,p){const o=s.orders.find(x=>x.id===p.id);if(!o)return missing('这笔订单不在当前空间','orders');return `${top('返回订单')}<span class="pill outline">DEMO · 非真实交易</span><h1 class="info-title">${App.orderLabel(o)}</h1><div class="order-heading"><div class="row between"><h2>${o.plan==='annual'?'年方案':'月方案'}</h2><span class="pill outline">原方案快照</span></div><p class="small muted space-12">${o.plan==='annual'?'12 个月方向':'1 个月方向'} · 本轮没有实际价格和权益</p></div><dl class="order-facts"><dt>订单编号</dt><dd>${esc(o.id)}</dd><dt>订单归属</dt><dd>本地演示身份 · 不是真实账号</dd><dt>内容版本</dt><dd>${esc(o.planVersion)}</dd><dt>支付事实</dt><dd>${o.payment==='paid'?'模拟已支付':o.payment==='refunding'?'模拟退款处理中':o.payment==='refunded'?'模拟已退款':'尚未核验（演示）'}</dd><dt>权益状态</dt><dd>${o.entitlement==='active'?'模拟已生效':o.entitlement==='revoked'?'模拟已撤回':'模拟待生效'}</dd><dt>实际扣款</dt><dd>无</dd></dl><ol class="step-list"><li>保留所选方案<p>这里显示的是创建订单时选择的方案。</p></li><li>核验付款事实<p>状态未知时查询原单，不重新购买。</p></li><li>核对权益<p>付款成功与权益生效是不同状态。</p></li></ol>${o.payment==='pending'?B('演示：付款已核验','order-paid',{cls:'btn full','data-id':o.id}):o.payment==='paid'&&o.entitlement!=='active'?B('演示：权益已生效','order-active',{cls:'btn full','data-id':o.id}):o.payment==='paid'?B('查看退款申请演示','refund',{cls:'btn secondary full','data-id':o.id}):o.payment==='refunding'?B('查看退款进度说明','refund-info',{cls:'btn secondary full','data-id':o.id}):''}${B('回到原来的任务','order-return',{cls:'btn tonal full space-12','data-id':o.id})}<div class="hint space-24">所有状态都只在本机演示，没有实际扣款，也不能办理真实退款或恢复购买。</div>`;}
 function article(s,p){return `${top('认识')}<span class="overline">理解的方法</span><h1 class="info-title">高一点、低一点，<br>都不代表更好。</h1><p class="small muted">从具体情境理解倾向</p><div class="report-body space-24"><p>看到一只装得更满的瓶子，我们很容易把它理解成“更优秀”。但在性格探索里，倾向的位置不是奖励分。</p><blockquote class="quote" id="article-excerpt">一个人在陌生聚会里先听一会儿，不等于他不会表达；在熟悉的小团队里，他可能有完全不同的状态。</blockquote><p>对一个人的理解，需要具体情境。你可以看一看：当时和谁在一起，发生了什么，自己需要什么。先保留这些线索，再判断哪些解释适合自己。</p><h2 class="space-24">没有依据的地方，先留白</h2><p class="space-12">未知不是零。假设和本人补充，需要与测评结果分开看。</p><h2 class="space-24">不太符合，也值得写下来</h2><p class="space-12">你可以质疑一段解释、补上当时的情境。这是在丰富对自己的理解，而不是“答错了”。</p></div><div class="hint space-24">知遇测评 · 阅读笔记</div>${B('引用这段聚会情境','article-quote',{cls:'btn full space-24',icon:'chat'})}<p class="small muted space-12">将携带上方聚会情境的具体片段与出处；可移除，不会自动发送。</p>`;}
 function share(s){const sample=UI.sampleShare(s.reportContext);return `${top('返回报告')}<h1 class="info-title">预览分享图</h1><p class="small muted">先看实际内容。导出之后，文件不能由本应用远程撤回。</p><div class="card space-24" id="share-preview"><span class="pill outline">知遇测评</span><p class="small muted space-12">${esc(sample.context)}</p><h2 class="space-16">${esc(sample.lines.join(''))}</h2><p class="small muted space-12">${esc(sample.body)}</p><hr class="hairline"><p class="small muted">不含姓名与本人补充</p></div><div class="hint space-16">分享图只包含上方内容，不包含本人补充、聊天或原始答案。</div>${B('导出这张分享图','export-share',{cls:'btn full space-24',icon:'download'})}`;}
 function settings(s){return `${top('我的')}<h1 class="info-title">简单一点，刚刚好</h1><div class="plain-list space-24">${row('主题与形象','八套主题、独立人物选择','appearance','palette')}${row('阅读密度与动态','舒展、紧凑与减少动态','','filter','',{action:'v3-preferences'})}${row('隐私与引用','聊天、记忆、外发分别控制','privacy','shield')}${row('账号与安全','管理账号与本机资料','account','user')}${row('我的数据','导出与清理范围','data','folder')}${row('使用说明','保存问题与使用反馈','support','help')}</div>${section('文字大小')}<div class="segmented">${[['normal','标准'],['large','大字']].map(([id,label])=>`<button data-action="font-size" data-id="${id}" class="${s.fontSize===id?'selected':''}" aria-pressed="${s.fontSize===id}">${label}</button>`).join('')}</div><div class="hint space-24">没有额外申请麦克风、相机、通知或定位。系统权限在真实功能需要时再申请，拒绝无关权限不应阻断本地测评。</div>`;}
 function privacy(s){return `${top('返回')}<h1 class="info-title">用到什么，<br>由你看见。</h1><p class="muted">一次引用、聊天留存、长期记忆，<br>用三个清楚的边界来管理。</p><div class="plain-list space-24">${row('本次资料引用','每次发送前选择，可逐条移除','','link','查看',{action:'context-spec'})}</div><div class="switch-row"><span class="grow">保存后续演示对话<span class="small muted" style="display:block">关闭后，新对话仅在本次窗口内显示；既有对话不删除。</span></span><button class="switch ${s.chatRetention?'on':''}" role="switch" aria-checked="${s.chatRetention}" data-action="toggle-chat-retention" aria-label="保存后续演示对话"><span></span></button></div><div class="switch-row"><span class="grow">允许提出长期记忆候选<span class="small muted" style="display:block">候选仍需逐条确认；打开不自动采用。</span></span><button class="switch ${s.memoryEnabled?'on':''}" role="switch" aria-checked="${s.memoryEnabled}" data-action="toggle-memory" aria-label="允许提出长期记忆候选"><span></span></button></div><div class="plain-list space-24">${row('已有记忆的纠正与停用','停用后，不纳入新的演示引用','memories','memory')}${row('本机数据导出与清理','不等于账号注销或云端删除','data','folder')}${row('账号注销范围','仅设计流程，未接入真实账号','','user','方案',{action:'delete-account-spec'})}${row('设备私密保护','候选功能，未接入系统认证','','lock','方案',{action:'device-spec'})}</div><details open><summary>真实服务上线前还需要什么</summary><p>明确模型提供方、实际外发字段、服务端与供应商留存、删除的传播范围、适用人群、协议与支持渠道。这份原型不是正式隐私政策，也不宣称端到端加密或服务器已删除。</p></details>`;}
 function support(s){return `${top('返回')}<h1 class="info-title">有问题，不用自己猜</h1><div class="plain-list space-24">${row('哪些是真的，哪些是演示','本地交互 / 预写回复 / 未接入服务','','info','阅读',{action:'demo-boundary'})}${row('保存失败时怎么办','先留住输入，不要直接关页面','','help','阅读',{action:'save-help'})}${row('导出设计反馈','写下页面、问题和期望，下载为文本','','edit','导出',{action:'design-feedback'})}${row('协议与适用范围','正式文本待真实产品方案确定','','book','说明',{action:'terms-spec'})}</div><div class="card space-24"><span class="overline">关于本轮方案</span><h2 class="space-12">知遇测评 · 自我理解体验</h2><p class="small muted space-12">这是知遇测评的交互原型。你可以体验本机记录、整理和回看；正式测评、真实 AI 与云同步尚未接入。</p><p class="small muted space-12">界面版本 4.1 · 2026-10-02</p></div>${end('可导出反馈文本，暂不能提交给客服。')}`;}
 function account(s){return `${top('我的')}<h1 class="info-title">账号与本机空间</h1><div class="card space-24"><h2>${s.logged?'当前：本地演示身份':'当前：未登录'}</h2><p class="small muted space-12">本轮不验证手机号或邮箱，也不进行跨账号迁移。演示身份不等于真实账号，更不等于资料已经同步。</p></div><div class="plain-list space-24">${row('了解登录与注册','登录演示后回到原任务，不自动发送','auth','user')}${row('恢复账号','需要实际认证方式与恢复证据','','lock','方案',{action:'recover-spec'})}${row('注销账号的处理范围','区分本机、应用云端和外部服务','','trash','方案',{action:'delete-account-spec'})}</div>${s.logged?B('退出演示身份','logout',{cls:'btn secondary full space-24'}):L('了解登录与注册','auth',{cls:'btn full space-24'})}`;}
 function simulation(s){const f=D.factors.find(x=>x[0]===(App.simFactor||'A'));const val=App.simValue??50;return `${top('认识')}<span class="pill warm">假想设定</span><h1 class="info-title">设定一种假想性格</h1><p class="small muted">选择一个因子，调整它的假设位置。这里只预览位置，不生成性格分析。</p><div class="card space-24 center"><div style="width:72px;margin:0 auto">${bottle([f[0],f[1],val/100,f[3]])}</div><h2 class="space-16">${f[0]} · ${f[1]}</h2><label class="field-label space-16" for="sim-range">假设位置（不是测评分数）</label><input id="sim-range" type="range" min="10" max="90" value="${val}" data-input="sim-range" style="width:100%;accent-color:var(--primary)"><p class="small muted space-12">调整位置，看看这次想象中的倾向。</p></div><div class="plain-list space-24">${row('换一个因子','查看另一个因子的假设位置','','bottle','',{action:'sim-factors'})}</div>${end('假设是学习概念的一种方式，不是给自己打分。')}`;}
 function compare(s){return `${top('记录')}<h1 class="info-title">先确认，<br>能不能放在一起看。</h1><p class="muted">两份记录，不一定是一把尺子。</p><div class="card space-24"><div class="row">${icon('info')}<h3>当前没有两份可比较的正式结果</h3></div><p class="small muted space-12">三题演示、独立报告样例和本人观察，不能合成分数变化。先保留各自的来源与含义。</p></div><ol class="step-list"><li>选择两份结果<p>保留每份结果的来源、内容版本与计分版本。</p></li><li>核对可比依据<p>不同题源或量纲，只并列阅读，不画进步曲线。</p></li><li>结合当时的情境<p>不把一次差异直接解释为人格改变。</p></li></ol>${L('回到记录','records',{cls:'btn secondary full'})}`;}
 function content(s){return `${top('我的数据')}<h1 class="info-title">本机有哪些内容</h1><div class="card space-24"><span class="pill">已随包提供</span><h2 class="space-12">3 道原创交互示例</h2><p class="small muted space-12">demo-3-v1 · 不含正式 16PF 题目、计分或常模。断网后仍可使用已加载的示例文件。</p></div><div class="card space-16"><span class="pill outline">未就绪</span><h2 class="space-12">正式 16PF / AI 重置版</h2><p class="small muted space-12">正式题目和计分依据还未接入。目前可体验页面流程，不能取得个人测评分数。</p></div><div class="hint space-24">本轮没有真实下载、更新或撤回服务。正式内容更新不应改写旧答卷和已保存报告。</div>`;}
 function missing(text,route){return `${top('返回')}<div class="blank-illustration"><img src="assets/learning.svg" alt=""></div>${empty(text,'这份内容在当前浏览器中找不到。可以返回列表重新选择；其他已保存的资料不会被删除。',L('回到列表',route,{cls:'btn secondary'}))}`;}
 const map={home,explore,assistant,me,question,review,complete,report,records,topic,appearance,conversations,conversation,auth,memories,actions,journal,portrait,data,membership,checkout,orders,order,article,share,settings,privacy,support,account,simulation,compare,content};
 return {map,render(route,s,p){return (map[route]||(()=>missing('这个页面暂时不可用','home')))(s,p);},isRoot:route=>['home','explore','assistant','me'].includes(route)};
})();
